-- Public facts about four Michigan colleges for the second college plan (checked 2026-10-28).
-- Sources are inside each record. Re-run after refreshing the research.
update public.amy_colleges set facts = $fx${"coursework": {"summary": "U-M asks for 4 years of English with at least 2 rigorous writing courses, at least 2 lab sciences, and ideally five full-year academic courses in each of the four years. For Ross the table is 4 English, 2 world language (same language preferred), 4 math, 3 science, 3 social studies, 5 other. Ross says calculus is not required and that math records are viewed holistically.", "items": ["English: 4 years required (at least 2 rigorous writing courses)", "Math: 4 units required for Business (Ross), any math of the student's choice; calculus NOT required ('a student's math record is viewed holistically')", "Science: 3 units for Ross; at least 2 laboratory science courses required university-wide", "Social studies: 3 units", "World language: 2 years required (same language preferred); LSA strongly encourages 4 years", "Other/electives (arts etc.): 5 units for Ross; arts not specifically named", "Ideal: 5 full-year academic courses each of 4 years, plus AP/IB/honors/accelerated courses when appropriate and available"], "source": "https://admissions.umich.edu/apply/first-year-applicants/college-preparation (checked 2026-10-28)"}, "rigor_note": "U-M says the ideal applicant takes AP, IB, honors, enriched, and accelerated courses when appropriate and available. Its AP page names 11th grade as typically the best time to start AP/IB work. It also says that where AP is available, 'excessive AP participation is neither required nor encouraged', and that not having AP scores will not hurt a review. AP/IB results are read in context of the academic record. Sources: https://admissions.umich.edu/apply/first-year-applicants/college-preparation ; https://admissions.umich.edu/apply/first-year-applicants/ap-ib-credit ; https://admissions.umich.edu/apply/first-year-applicants/requirements-deadlines/application-changes (all checked 2026-10-28).", "ap_credit": {"table_url": "https://admissions.umich.edu/apply/first-year-applicants/ap-ib-credit/ap-guidelines", "note": "Ross awards AP hours by the LSA guidelines (IBE students follow Engineering). Ross accepts at most 30 credit hours earned before the first year, test and transfer combined. The guidelines page says it is 'current as of 2026' and subject to change. Checked 2026-10-28.", "courses": [{"course": "AP English Language", "min_score": "4", "credit": "ENGLISH 101x departmental, 3 cr; does NOT satisfy First-Year Writing"}, {"course": "AP English Literature", "min_score": "4", "credit": "ENGLISH 101x departmental, 3 cr; does NOT satisfy First-Year Writing (Lang + Lit = 6 cr total)"}, {"course": "AP Calculus AB", "min_score": "5", "credit": "MATH 120, 2 cr, plus 2 more after a C or better in the next course (Math 116 etc.); a 4 or lower earns no credit"}, {"course": "AP Calculus BC", "min_score": "4", "credit": "4 -> MATH 120 (2 cr, +2 after the next course); 5 -> MATH 120 + MATH 121 (4 cr, +4 after the next course). No credit for the AB subscore"}, {"course": "AP Statistics", "min_score": "4", "credit": "STATS 180, 3 cr"}, {"course": "AP Biology", "min_score": "3", "credit": "3 -> BIOLOGY 100 (4 cr); 4 -> BIOLOGY 195 (5 cr); 5 -> BIOLOGY 195 + 196 (6 cr)"}, {"course": "AP Chemistry", "min_score": "4", "credit": "CHEM 130 + CHEM 125/126, 5 cr"}, {"course": "AP Physics 1", "min_score": "not found (no credit alone)", "credit": "LSA gives credit only for a 5 on BOTH Physics 1 and Physics 2 (PHYSICS 125/127/126/128, 10 cr); Physics 1 alone earns no credit"}, {"course": "AP US History", "min_score": "4", "credit": "100-level HISTORY, 4 cr (does not count toward the History major)"}, {"course": "AP US Government", "min_score": "4", "credit": "POLSCI 111, 4 cr"}, {"course": "AP Psychology", "min_score": "4", "credit": "PSYCH 111, 4 cr"}, {"course": "AP Macroeconomics", "min_score": "4", "credit": "ECON departmental credit, 2 cr; NOT equivalent to ECON 102"}, {"course": "AP Microeconomics", "min_score": "4", "credit": "ECON departmental credit, 2 cr; NOT equivalent to ECON 101 and does not satisfy ECON 101 (so it does NOT meet the Ross ECON 101 requirement)"}, {"course": "AP Computer Science Principles", "min_score": "4", "credit": "EECS 101x departmental, 4 cr"}, {"course": "AP Spanish Language", "min_score": "4", "credit": "SPANISH 232 (4 cr; satisfies the LSA language requirement), plus SPANISH 279x (3 cr) after a B or better in SPANISH 277/278/RCLANG 324"}]}, "dual_enrollment": {"summary": "Community-college courses taken during high school can transfer to U-M if they are from an accredited college, of rigor and content similar to U-M courses, and earned a C or better. U-M does NOT accept the MTA as a block, because it has no general-education requirement. It evaluates each MTA course one at a time and posts the ones that transfer as transfer credit. Bay de Noc CC appears on U-M's list of MTA course evaluations; Bay College's courses can be checked in U-M's Transfer Credit Equivalency (TCE) database. Courses that don't closely match a U-M course come in as 'departmental credit', which counts only as electives and cannot meet prerequisites. New for fall 2027: some community-college math courses (U-M 102/111/112/211/212/213 categories) transfer as 'Subject Elective Credit'. Where a department needs equivalent math credit, a proficiency test is required. Ross caps pre-matriculation credit at 30 hours (test + transfer). Ross posts transferable DE credit, but only courses that already have an evaluation in the TCE database are eligible. All business credit is non-transferable, and transfer credit, once posted, cannot be removed.", "transfer_status_risk": "Taking DE courses while still in high school keeps you a first-year applicant. U-M: 'If you enrolled in college study after secondary school graduation, you must apply as a transfer student.' First-year applicants with DE must send official college transcripts. Watch-outs: (1) Ross class standing is set by credits (25+ = sophomore), which can affect tuition tier, though Ross caps pre-matriculation credit at 30 toward the degree. (2) Never take a college class in the summer after high school graduation before enrolling, or the student could be treated as a transfer applicant.", "ross_note": "What Ross states exactly (first-year applicant page, checked 2026-10-28): Calculus I, II, or III must be completed with a C- or better and 'including AP, IB or A-level credit for this course'. For first-year Ross students, 'approved transfer credit must be on your transcript by the end of Summer term after your first year', so AP Calc credit or an approved DE calculus course can meet it. Writing and economics are a different case: Ross requires 'the following two University of Michigan courses, each with a grade of C- or better, by the end of Winter term': (a) an LSA-approved First-Year Writing course and (b) 'Economics 101 (including IB or A-Level test credit for this course)'. AP Micro gives only 2 departmental credits, and the U-M AP table says it 'will not satisfy ECON 101 requirements'. The only exceptions Ross lists are IB and A-level. AP English credit does not satisfy First-Year Writing. Ross also must take BA 100, BCOM 250 and ACC 300 at Ross in the first year. Ross's Summer 2025 Test and Transfer Credit Guide says DE credit can count toward BBA requirements but 'All Business credit is non-transferable'. Read literally, a Bay College ECON or ENG 101 course would NOT replace the Ross ECON 101 or First-Year Writing requirement, since both must be U-M courses. The Ross pages do not explicitly address DE ECON, so confirm with the Ross Registrar (bbacrediteval@umich.edu). Also unverified: whether a community-college calculus course will count as 'Calculus I' under U-M's new fall-2027 'Subject Elective Credit' rule for transferred math.", "source": "https://michiganross.umich.edu/undergraduate/bba/admissions/first-year-applicants ; https://rossweb.bus.umich.edu/academics/wp-content/uploads/sites/2/2025/10/2025fyentrytransfercreditguide.pdf ; https://admissions.umich.edu/apply/transfer-applicants/transfer-credit ; https://admissions.umich.edu/apply/transfer-applicants/community-college-students/michigan-transfer-agreement ; https://admissions.umich.edu/apply/first-year-applicants/requirements-deadlines (all checked 2026-10-28)"}, "testing": {"policy": "Test-optional for the 2026-27 cycle (fall 2027 entry). U-M says it 'will review the policy on an ongoing basis'. No policy has been published yet for fall 2029 entry. U-M accepts self-reported scores and superscores, and says applicants are not disadvantaged without SAT/ACT. Ross's page also says U-M is test optional.", "middle50": "All of U-M Ann Arbor, enrolled Fall 2024 (25th-75th percentile): HS GPA 3.9-4.0; SAT ERW 680-750; SAT Math 680-780 (51% submitted SAT); ACT 31-34 (18% submitted). Fall 2025 figures are listed as 'TBD'. Ross admitted Fall 2026 class: average HS GPA 3.94, average SAT 1470, average ACT 33; 13,596 applicants, 951 admitted. These are Ross averages, not a middle 50%.", "source": "https://admissions.umich.edu/apply/first-year-applicants/requirements-deadlines/application-changes ; https://obp.umich.edu/wp-content/uploads/pubdata/factsfigures/firstyearsprofile_umaa_2025.pdf (dated 9/22/2025) ; https://michiganross.umich.edu/undergraduate/bba/admissions/first-year-applicants (all checked 2026-10-28)"}, "summer_programs": [{"name": "Michigan Ross Summer Business Academy", "grades": "Rising high school seniors only (the student would be eligible for summer 2028, after 11th grade)", "when_to_apply": "2027 application opens November 2026, deadline Jan. 10, 2027 at 11:59 p.m. EST, decisions end of March 2027, sessions in June. Expect a similar Nov-Jan window in 2027-28 for the student's summer 2028.", "cost": "2027 fee not posted on the page. The prior official listing showed a $5,500 fee for the 2025 two-week academy plus a $75 application fee, with need-based scholarships (seen via search snippet of an official Ross page, not re-verified). No college credit, and it does not affect BBA admission.", "url": "https://michiganross.umich.edu/undergraduate/summer-business-academy"}, {"name": "Michigan Math and Science Scholars (MMSS)", "grades": "Rising sophomores, juniors, or seniors (at least age 14; must have completed 1 year of HS). the student is eligible for summer 2027 and 2028.", "when_to_apply": "2027 application opens mid-January 2027, with rolling admission until courses fill (apply early). 2027 sessions: June 20-July 2, July 4-16, July 18-30.", "cost": "2026 fees: $100 non-refundable application fee + $1,400 tuition + $1,100 residential per two-week session (commuters skip housing). Financial aid page available. 2027 fees not yet posted.", "url": "https://sites.lsa.umich.edu/mmss/"}, {"name": "U-M Center for Educational Outreach - K-12 summer program listing", "grades": "K-12", "when_to_apply": "Varies by program", "cost": "Varies", "url": "https://admissions.umich.edu/apply/first-year-applicants/college-preparation"}], "checked_on": "2026-10-28"}$fx$::jsonb where name = 'University of Michigan';
update public.amy_colleges set facts = $fx${"coursework": {"summary": "MSU's stated minimum is 4 English, 3 math (2 algebra + 1 geometry), 3 social studies, 2 science, and 2 years of one world language. It recommends a majority of core academic courses every semester, including 3 core courses in senior year. On its advanced-credits page MSU also says high school math should reach 'at least a calculus preparatory level'. Calculus itself is not required.", "items": ["English: 4 years (composition and literature)", "Math: 3 years minimum (2 algebra, 1 geometry). Math should reach at least calculus-preparatory level; calculus not required", "Science: 2 years (biology, chemistry, physics, or earth science); lab not specified", "Social studies: 3 years (history, government, economics, etc.)", "World language: 2 years of a single language", "Arts: not mentioned", "Broad Direct Admission: 3.5+ HS GPA at time of MSU admission to be considered"], "source": "https://admissions.msu.edu/apply/first-year/admission-criteria ; https://admissions.msu.edu/apply/first-year/advanced-credits ; https://broad.msu.edu/undergraduate/admissions/direct/ (checked 2026-10-28)"}, "rigor_note": "MSU encourages honors, AP, and IB courses when possible, and recommends most core academic courses each semester with 3 in senior year. It warns that 'a less rigorous curriculum will put these applications at a disadvantage'. On the advanced-credits page MSU suggests considering the high school's AP or IB courses before dual enrolling. Sources: https://admissions.msu.edu/apply/first-year/admission-criteria ; https://admissions.msu.edu/counselors (checked 2026-10-28).", "ap_credit": {"table_url": "https://edge.sitecorecloud.io/michiganstab57e-msustrategi129d-prod9868-7e5e/media/Project/MSU/Admissions/Docs/msu-ap-equivalencies.pdf", "note": "MSU AP Equivalencies chart, 'Updated: 4-7-2025'. A 'waiver' gives 0 credit. Broad says AP waivers of WRA 101, EC 201 and EC 202 do NOT fulfill Broad requirements, so credit must be earned. Checked 2026-10-28.", "courses": [{"course": "AP English Language", "min_score": "4", "credit": "4 or 5 -> WRA 101 (4 cr). A 3 -> waiver of WRA 101 (0 cr), which does NOT satisfy the Broad Tier I writing precore"}, {"course": "AP English Literature", "min_score": "4", "credit": "4 or 5 -> WRA 101 (4 cr). With BOTH English exams: 5 -> WRA 101 + ENG 210; 4 -> WRA 101 + ENG GCU (3 cr). A 3 -> waiver only"}, {"course": "AP Calculus AB", "min_score": "4", "credit": "MTH 132 (3 cr)"}, {"course": "AP Calculus BC", "min_score": "3", "credit": "MTH 132 + MTH 133 (7 cr)"}, {"course": "AP Statistics", "min_score": "4", "credit": "STT 200 (3 cr); a Broad precore course"}, {"course": "AP Biology", "min_score": "4", "credit": "BS 161, 162 & waive BS 171, 172 (8 cr); a 3 earns no credit"}, {"course": "AP Chemistry", "min_score": "3", "credit": "3 -> CEM 141, 161 (5 cr); 4 or 5 -> CEM 151, 152, 161 (8 cr)"}, {"course": "AP Physics 1", "min_score": "4", "credit": "PHY 231 (3 cr)"}, {"course": "AP US History", "min_score": "3", "credit": "HST 202, 203 (8 cr); a 2 gives a waiver"}, {"course": "AP US Government", "min_score": "4", "credit": "PLS 100 (3 cr); a 3 gives a waiver"}, {"course": "AP Psychology", "min_score": "4", "credit": "PSY 101 (4 cr)"}, {"course": "AP Macroeconomics", "min_score": "4", "credit": "EC 202 (3 cr), a Broad precore course. A 3 gives a waiver only, which does NOT satisfy Broad"}, {"course": "AP Microeconomics", "min_score": "4", "credit": "EC 201 (3 cr), a Broad precore course. A 3 gives a waiver only, which does NOT satisfy Broad"}, {"course": "AP Computer Science Principles", "min_score": "1", "credit": "3 cr CSE GCU (general credit) for any score 1-5, per the chart"}, {"course": "AP Spanish Language", "min_score": "3", "credit": "3 -> SPN 202 (4 cr); 4 -> SPN 201, 202 (8 cr); 5 -> SPN 201, 202, 310 (11 cr)"}]}, "dual_enrollment": {"summary": "MSU may grant credit for college courses taken in high school at an accredited institution. Official transcripts must come directly from the college. Course-by-course equivalencies are at transfercredit.msu.edu. Transfer credit needs a grade of 2.0 or higher. At most 60 semester credits from two-year colleges count toward the bachelor's degree. MSU participates in the MTA: an 'MTA Satisfied' notation on a community-college transcript satisfies MSU's general education requirements (each MTA course needs 2.0+). A waived university requirement does not waive a course used as a prerequisite. Early/middle college applicants transferring 42 or more credits must choose a major. Broad accepts course-specific transfer equivalencies exactly as listed on Transfer MSU, but 'GCU' (general credit) will not fulfill College Precore courses. Broad direct admits must complete STT 200, WRA 101/195H, EC 201 and EC 202 'with credit', plus a 3.0 cumulative GPA, a 3.0 precore GPA and 28 credits, within 3 fall/spring semesters. AP/IB/CLEP precore credit counts as a 4.0 in the precore GPA only if the student has fewer than two MSU-graded precore courses. Transfer (DE) precore grades are used only if the student has 0 or 1 MSU-graded precore course. With two or more MSU-graded precore courses, only MSU grades count.", "transfer_status_risk": "Low. MSU Admissions says students who earned dual enrollment credit in high school 'should apply as a first-year student'. Only students who enroll at a college after high school graduation apply as transfers. Broad's Direct Admission FAQ says AP, DE, or Early College credit 'does not change their status to transfer students', and that 'No weight is given to the presence or number of such credits' in direct admission review.", "ross_note": "Not applicable (U-M only). Broad equivalent: DE courses that transfer as the exact MSU course (for example EC 201, EC 202, STT 200, WRA 101) CAN satisfy Broad precore requirements. Courses that transfer only as GCU cannot. AP waivers (score of 3 on English or Econ) cannot.", "source": "https://admissions.msu.edu/apply/first-year/advanced-credits ; https://admissions.msu.edu/apply/transfer/transfer-credits ; https://reg.msu.edu/ROInfo/MITransferAgreement.aspx ; https://broad.msu.edu/undergraduate/admissions/direct/ ; https://broad.msu.edu/undergraduate/admissions/standard/ (all checked 2026-10-28)"}, "testing": {"policy": "Test-optional for first-year applicants. The page states no end date and names no specific terms. Broad direct admission does not consider ACT/SAT. Nothing has been published specifically for fall 2029.", "middle50": "Fall 2026 first-year class (middle 50%): HS GPA 3.5-4.0; SAT 1100-1320; ACT 25-31; 9,657 entering students.", "source": "https://admissions.msu.edu/apply/first-year/admission-criteria ; https://admissions.msu.edu/apply/first-year/act-sat-test-optional ; https://broad.msu.edu/undergraduate/admissions/direct/ (checked 2026-10-28)"}, "summer_programs": [{"name": "MSU Entrepreneur Leadership High School Camp (Broad College, Burgess Institute + Multicultural Business Programs)", "grades": "2026 listing: rising high school juniors and seniors (a 2024 article said rising sophomores and juniors, so eligibility has changed between years)", "when_to_apply": "2026 application deadline was April 10 for a June 22-25 camp. 2027 dates are not posted yet, so watch for a February posting.", "cost": "Free (4-day residential camp)", "url": "https://entrepreneurship.msu.edu/news/2026/02/04/high-school-camp-applications-now-open"}, {"name": "Spartan Youth Programs (MSU directory of 200+ pre-college programs)", "grades": "PreK-12; searchable by grade/topic incl. business; some offer college credit and overnight stays", "when_to_apply": "Varies by program; register on each program's own site", "cost": "Varies; financial aid available for some programs", "url": "https://spartanyouth.msu.edu/about/overview/"}], "checked_on": "2026-10-28"}$fx$::jsonb where name = 'Michigan State University';
update public.amy_colleges set facts = $fx${"coursework": {"summary": "Michigan Tech lists these as 'recommendations, not requirements for admission'. Requirements vary by major, and the committee reviews the courses taken and the grades earned.", "items": ["English: 3-4 years", "Math: 3-4 years (Sciences & Arts, Forest Resources); 4 years 'with progression towards or including Calculus' for Engineering/Computing, and most majors start at Calculus", "Science: 3 years incl. physics for Engineering/Computing (chemistry also suggested for Engineering); biology + chemistry for Forest Resources", "Social science: 3 years", "World language: 2 years recommended (not required)", "Computer literacy: 1 year recommended", "Arts: not mentioned"], "source": "https://www.mtu.edu/admissions/apply/requirements/ (checked 2026-10-28)"}, "rigor_note": "Michigan Tech says admission requirements vary by major and that it reviews the courses taken and the grades received. It uses the cumulative HS GPA, taking whichever of weighted or unweighted works best, and does not recalculate it. No specific AP/IB/DE rigor statement was found. Source: https://www.mtu.edu/admissions/apply/requirements/ (checked 2026-10-28).", "ap_credit": {"table_url": "https://www.mtu.edu/admissions/enroll/ap-ib-clep/ap/", "note": "Table for students entering 2026-27. Official scores must come from College Board (code 1464). Checked 2026-10-28.", "courses": [{"course": "AP English Language", "min_score": "3", "credit": "UN 1015 (3 cr)"}, {"course": "AP English Literature", "min_score": "3", "credit": "HU 2503 (3 cr)"}, {"course": "AP Calculus AB", "min_score": "4", "credit": "4 or 5 -> MA 1160 (4 cr). A 3 -> may enroll in MA 2160, with MA 1160 awarded after a C or better. A 2 -> may enroll in MA 1161"}, {"course": "AP Calculus BC", "min_score": "4", "credit": "4 or 5 -> MA 1160 + MA 2160 (8 cr). A 3 -> may enroll in MA 3160, with 8 cr awarded after a C or better. A 2 or lower -> AB-subscore rules"}, {"course": "AP Statistics", "min_score": "3", "credit": "MA 2710 (3 cr)"}, {"course": "AP Biology", "min_score": "3", "credit": "3 or 4 -> BL 1400, 1410 (4 cr); 5 -> BL 1100, 1110, 1200, 1210 (8 cr)"}, {"course": "AP Chemistry", "min_score": "3", "credit": "3 -> CH 1150/1151/1153 (5 cr); 4 or 5 -> CH 1150/1151/1153/1160/1161/1163 (10 cr)"}, {"course": "AP Physics 1", "min_score": "4", "credit": "PH 1110, PH 1111 (4 cr)"}, {"course": "AP US History", "min_score": "3", "credit": "SS 2500 (3 cr)"}, {"course": "AP US Government", "min_score": "3", "credit": "SS 2600 (3 cr)"}, {"course": "AP Psychology", "min_score": "3", "credit": "PSY 2000 (3 cr)"}, {"course": "AP Macroeconomics", "min_score": "3", "credit": "ECA (3 cr). A 4+ on BOTH econ exams also earns EC 2001 (3 cr) plus 3 cr of approved economics credit"}, {"course": "AP Microeconomics", "min_score": "3", "credit": "ECA (3 cr); same both-exams rule as Macro"}, {"course": "AP Computer Science Principles", "min_score": "3", "credit": "TRU XXXX (3 cr)"}, {"course": "AP Spanish Language", "min_score": "3", "credit": "3 -> HU 2293, 3291, 3292 (9 cr) after completing HU 3293; 4 or 5 -> HU 3291, 3292, 3293 (9 cr) after completing HU 3294/3295/3296"}]}, "dual_enrollment": {"summary": "Transfer credit is granted for appropriate courses from accredited institutions with a grade of C or better. It can meet both general-education and degree-specific requirements, and Michigan Tech has a transfer equivalency tool. For 2025-26 and later catalogs, a transcript marked 'MTA Satisfied' fulfills all Essential Education requirements (2.0 minimum in each MTA course). Partial MTA is evaluated course by course. No overall transfer-credit cap was found. Two notes: AP/IB/CLEP credit that another college awarded does not transfer, so send AP scores directly. Students with 60+ credits (including DE/AP) are charged upper-division tuition.", "transfer_status_risk": "Low. Students in early/middle college programs are 'considered first-year students' for admission and scholarships. DE applicants seeking full-time degree admission 'follow the directions for a first-year student'. No page says DE credits change applicant status. The main side effect is the 60-credit upper-division tuition rule.", "ross_note": "Not applicable (U-M only).", "source": "https://www.mtu.edu/admissions/connect/transfer/ ; https://www.mtu.edu/admissions/apply/dual/ ; https://www.mtu.edu/registrar/students/transfer/mta/index.html (checked 2026-10-28)"}, "testing": {"policy": "Test scores are optional for domestic students (the 2027 application is live). Scores are required if HS GPA is below 3.00, and are used only if they strengthen the application. Scholarships are available without scores. Nothing has been published specifically for fall 2029.", "middle50": "Middle 50% not found. Averages: HS GPA 3.83, SAT 1221; 51.7% of first-years in the top 20% of their class.", "source": "https://www.mtu.edu/admissions/apply/steps/index.html ; https://www.mtu.edu/admissions/apply/requirements/ (checked 2026-10-28)"}, "summer_programs": [{"name": "Michigan Tech Summer Youth Programs (SYP) - week-long Explorations", "grades": "Grades 6-11 (register by current grade; current 12th graders are not eligible). the student is eligible for summers 2027 and 2028.", "when_to_apply": "2027 registration date not posted. 2026 registration opened in early 2026. Sessions run mid-June to mid-July. A $150 non-refundable deposit is due at registration and the balance by May 1.", "cost": "Base cost $1,175 live-in / $700 commuter (year not stated on the page; appears to be 2026). Scholarships available.", "url": "https://www.mtu.edu/syp/"}, {"name": "SYP Pathway Programs (e.g., Engineering Scholars Program, Women in Engineering, Women in Computer Science, sponsored/no-cost tracks)", "grades": "Grades 9-11", "when_to_apply": "2026 cycle: applications completed by Feb. 15 were considered in the first round, then rolling review from March 1. Expect a similar deadline (about mid-February) in 2027.", "cost": "$0 due at application; program fee due within 10 days of acceptance. Fees vary, several tracks are fully sponsored, and every applicant is considered for aid.", "url": "https://www.mtu.edu/syp/discover/pathway-programs/"}], "checked_on": "2026-10-28"}$fx$::jsonb where name = 'Michigan Technological University';
update public.amy_colleges set facts = $fx${"coursework": {"summary": "Michigan students should follow the Michigan Merit Curriculum. NMU prefers 4 years each of English, college-prep math, social studies and science, plus 2 years of a language. Students should earn 12-16 credits in these areas by the end of senior year. Admission is automatic at a cumulative HS GPA of 2.25 or higher.", "items": ["English: 4 years preferred", "Math: 4 years college-prep preferred; calculus not mentioned", "Science: 4 years preferred; lab not specified", "Social studies: 4 years preferred", "World language: 2 years preferred", "Arts and information technology: encouraged"], "source": "https://nmu.edu/admissions/freshmen (checked 2026-10-28)"}, "rigor_note": "No specific AP/IB/DE rigor statement found. Admission is GPA-based: 2.25+ is admitted. Below 2.25, NMU reviews courses, grades, grade trend and program, and may admit conditionally. If the school reports more than one GPA, NMU uses the higher. Source: https://nmu.edu/admissions/freshmen ; https://nmu.edu/bulletin/undergraduate-admissions-policies (checked 2026-10-28).", "ap_credit": {"table_url": "https://www.nmu.edu/bulletin/exam-equivalencies", "note": "From the NMU Bulletin 'AP Examination Equivalencies' page, which is marked archived and has no catalog year. The current catalog version (nmu.edu/page-links/pages/exam-equivalencies, which redirects to catalog.nmu.edu) would not load for verification. Checked 2026-10-28.", "courses": [{"course": "AP English Language", "min_score": "3", "credit": "EN 111 College Composition I (4 cr)"}, {"course": "AP English Literature", "min_score": "3", "credit": "EN 111 or EN 247 Intro to Literary Studies (4 cr)"}, {"course": "AP Calculus AB", "min_score": "3", "credit": "MA 161 Calculus I (4 cr)"}, {"course": "AP Calculus BC", "min_score": "3", "credit": "MA 161 + MA 163 Calculus I & II (4 cr each)"}, {"course": "AP Statistics", "min_score": "3", "credit": "DATA 109 Introduction to Statistics (4 cr)"}, {"course": "AP Biology", "min_score": "3", "credit": "BI 111 + BI 112 (4 cr each)"}, {"course": "AP Chemistry", "min_score": "3", "credit": "CH 111 + CH 112 General Chemistry I & II (5 cr each)"}, {"course": "AP Physics 1", "min_score": "3", "credit": "PH 201 College Physics I (5 cr)"}, {"course": "AP US History", "min_score": "3", "credit": "HS 221 + HS 222 (4 cr each)"}, {"course": "AP US Government", "min_score": "3", "credit": "PS 105 American Government (4 cr)"}, {"course": "AP Psychology", "min_score": "4", "credit": "PSY 101 General Psychology (3 cr)"}, {"course": "AP Macroeconomics", "min_score": "3", "credit": "EC 202 Macroeconomic Principles (4 cr)"}, {"course": "AP Microeconomics", "min_score": "3", "credit": "EC 201 Microeconomic Principles (4 cr)"}, {"course": "AP Computer Science Principles", "min_score": "3", "credit": "CS 295 Special Topics in CS (4 cr)"}, {"course": "AP Spanish Language", "min_score": "3", "credit": "SN 202 Intermediate Spanish II (4 cr)"}]}, "dual_enrollment": {"summary": "Transfer courses need a C- or better to post (departments may require more). Up to 90 semester hours transfer from regionally accredited community colleges. 'MTA Satisfied' meets NMU General Education, but students must still complete world cultures, math competency, written competency and lab requirements. Partial MTA is evaluated course by course. Students who took college courses in high school send an official college transcript, which is not needed for admission but is required for credit. NMU's own dual enrollment requires a completed 10th grade, a 3.00 HS GPA, and at most 8 credits per semester. The policy page notes a consortium-program exception for Bay de Noc and Gogebic dual enrollees.", "transfer_status_risk": "Low. Applicants who have not attended college after high school are 'considered first-year or freshman applicants'. Transfer GPA rules apply only to college courses taken after high school graduation.", "ross_note": "Not applicable (U-M only).", "source": "https://nmu.edu/bulletin/transfer-credit-policy ; https://nmu.edu/admissions/freshmen ; https://nmu.edu/bulletin/undergraduate-admissions-policies (checked 2026-10-28; bulletin pages may be archived versions)"}, "testing": {"policy": "Test-free. 'NMU does not use ACT or SAT scores in making admissions or scholarship decisions.' Scores are considered only if an applicant below a 2.25 GPA chooses to submit them. Nothing has been published specifically for fall 2029.", "middle50": "not found (NMU publishes no test-score profile; the admission threshold is a 2.25 HS GPA)", "source": "https://nmu.edu/admissions/freshmen (checked 2026-10-28)"}, "summer_programs": [{"name": "NMU Environmental Science Camp", "grades": "High school students (grade levels not specified)", "when_to_apply": "2026 session ran July 12-18. Registration deadline not listed.", "cost": "not found", "url": "https://nmu.edu/events-and-announcements/environmental-science-camp"}, {"name": "U.P. Future Health Leaders Camp (with MSU College of Osteopathic Medicine)", "grades": "Incoming 9th and 10th graders (the student would age out after summer 2027 as an incoming junior; check eligibility)", "when_to_apply": "Held in July (2026: July 19-24). Registration timing not stated.", "cost": "not found", "url": "https://nmu.edu/ruralhealth/health-camp"}, {"name": "GenCyber Camp (Seaborg Center)", "grades": "High school (grade levels not specified)", "when_to_apply": "not found (latest listing seen was 2024)", "cost": "Free (two-week residential)", "url": "https://nmu.edu/seaborg/student-programs"}, {"name": "NMU Youth Programs directory", "grades": "Middle and high school", "when_to_apply": "Varies", "cost": "Varies", "url": "https://www.nmu.edu/youth-programs"}], "checked_on": "2026-10-28"}$fx$::jsonb where name = 'Northern Michigan University';
